    start_seq = entry.get("event_count", 0) if entry else 0

    new_raw = raw_events[raw_watermark:]
    if not new_raw:
        return 0

    contest_events = []
    for raw in new_raw:
        contest_events.extend(expand_claude_event(raw, fallback_ts=iso_now()))

    if not contest_events:
        if entry is not None:
            entry["raw_event_count"] = len(raw_events)
            write_manifest(member_dir, manifest, team_id, github_login, tool)
        return 0

    redact_rules = load_redact_rules(member_dir)
    if entry and entry.get("file_path"):
        existing_rel = entry["file_path"].split(f"{github_login}/", 1)[-1] \
            if f"{github_login}/" in entry["file_path"] else None
        if existing_rel:
            jsonl_path = member_dir / existing_rel
        else:
            jsonl_path = member_dir / local_date() / f"{tool}__{session_id}.jsonl"
    else:
        jsonl_path = member_dir / local_date() / f"{tool}__{session_id}.jsonl"

    try:
        result = append_events(jsonl_path, contest_events, session_id, team_id, github_login, tool, start_seq, redact_rules)
    except Exception as e:
        report_error(member_dir, "jsonl_append", {"tool": tool, "jsonl_path": str(jsonl_path)}, e)
        return 1

    new_event_count = (entry.get("event_count", 0) if entry else 0) + result["written"]
    rel_path = f"logs/{github_login}/{local_date()}/{tool}__{session_id}.jsonl"

    if is_new:
        first_ts = (raw_events[0].get("timestamp") if raw_events else None) or iso_now()
        entry = {
            "session_id": session_id,
            "tool": tool,
            "started_at": first_ts,
            "last_event_at": iso_now(),
            "event_count": new_event_count,
            "raw_event_count": len(raw_events),
            "file_path": rel_path,
            "collection_mode": "cli",
            "health": "ok",
        }
        last_assistant = next((e for e in reversed(raw_events) if (e.get("message") or {}).get("model")), None)
        if last_assistant:
            model = last_assistant.get("message", {}).get("model")
            if model:
                entry["model"] = model
        manifest.setdefault("sessions", []).append(entry)
    else:
        entry["last_event_at"] = iso_now()
        entry["event_count"] = new_event_count
        entry["raw_event_count"] = len(raw_events)
        entry["file_path"] = rel_path
        if result["redacted"] > 0:
            entry["redacted_count_total"] = entry.get("redacted_count_total", 0) + result["redacted"]

    write_manifest(member_dir, manifest, team_id, github_login, tool)

    auto_export_to_repo(
        repo_root, member_dir, jsonl_path, session_id,
        team_id, github_login, tool,
    )

    sys.stderr.write(
        f"[session-log] captured {result['written']} event(s) -> {rel_path}\n"
    )

    return 0


def auto_export_to_repo(repo_root: Path, staging_member_dir: Path, staging_jsonl: Path,
                        session_id: str, team_id: str, github_login: str, tool: str) -> None:
    try:
        dest_member = repo_root / "logs" / github_login
        dest_jsonl = dest_member / staging_jsonl.relative_to(staging_member_dir)
        dest_jsonl.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(staging_jsonl, dest_jsonl)

        actual_count = sum(1 for line in dest_jsonl.read_text(encoding="utf-8").splitlines() if line.strip())

        staging_manifest = read_manifest(staging_member_dir, team_id, github_login, tool)
        src_entry = next((s for s in staging_manifest.get("sessions", [])
                          if s.get("session_id") == session_id), None)
        if src_entry is None:
            return
        src_entry["event_count"] = actual_count
        src_entry["file_path"] = f"logs/{github_login}/{staging_jsonl.relative_to(staging_member_dir)}"

        dest_manifest = read_manifest(dest_member, team_id, github_login, tool)
        existing = next((s for s in dest_manifest.get("sessions", [])
                         if s.get("session_id") == session_id), None)
        if existing:
            existing.update(src_entry)
        else:
            dest_manifest.setdefault("sessions", []).append(src_entry)
        write_manifest(dest_member, dest_manifest, team_id, github_login, tool)
    except Exception as e:
        report_error(staging_member_dir, "auto_export", {"repo_root": str(repo_root), "session_id": session_id}, e)


def load_env_file() -> None:
    env_path = Path.home() / ".claude" / "contest-collector.env"
    if not env_path.is_file():
        return
    try:
        for line in env_path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" in line:
                key, val = line.split("=", 1)
                key = key.strip()
                val = val.strip().strip('"').strip("'")
                if key and key not in os.environ:
                    os.environ[key] = val
    except Exception:
        pass

def _validate_one_member(
    member_dir: Path,
    repo_root: Path,
    manifest_validator: Draft7Validator,
    event_validator: Draft7Validator,
    report: Report,
) -> None:
    manifest_path = member_dir / "manifest.json"

    if not manifest_path.exists():
        report.err(f"{manifest_path}: manifest.json not found in member directory")
        return

    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        report.err(f"{manifest_path}: invalid JSON: {e}")
        return

    for err in manifest_validator.iter_errors(manifest):
        loc = "$" + "".join(
            f"[{p!r}]" if isinstance(p, int) else f".{p}" for p in err.absolute_path
        )
        report.err(f"{manifest_path}: {loc}: {err.message}")

    if "team_id" not in manifest or "sessions" not in manifest:
        return

    team_id = manifest["team_id"]
    github_login = manifest.get("github_login", "")
    if github_login != member_dir.name:
        report.err(
            f"{manifest_path}: manifest.github_login={github_login!r} but parent "
            f"directory is {member_dir.name!r}"
        )

    declared_files: set[Path] = set()

    for idx, session in enumerate(manifest.get("sessions", [])):
        if not isinstance(session, dict):
            continue
        rel_path = session.get("file_path", "")
        sid = session.get("session_id", f"<unknown-{idx}>")
        tool = session.get("tool", "")

        # file_path is "logs/<github_login>/<date>/<tool>__<sid>.jsonl" relative
        # to the demo repo root. We try multiple resolution bases for robustness.
        candidates = [
            repo_root / rel_path,
            member_dir.parent.parent / rel_path,
            member_dir / rel_path.removeprefix(f"logs/{member_dir.name}/"),
        ]
        jsonl_path = None
        for c in candidates:
            if c.exists():
                jsonl_path = c
                break
        if jsonl_path is None:
            report.err(
                f"{manifest_path}: session[{idx}] {sid!r}: declared file_path "
                f"{rel_path!r} does not exist"
            )
            continue

        # Collector versions before 2026-07-10 split one session across
        # daily date files (logs/<login>/<date>/<tool>__<sid>.jsonl) while
        # the manifest kept a single entry with the cumulative count and
        # the last day's file_path. Gather every file of this session so
        # the whole stream is validated together, the cumulative count is
        # compared against the aggregate, and sibling files are not
        # mis-flagged as orphans.
        session_files = {
            p for p in member_dir.glob("*/*.jsonl")
            if p.name == f"{tool}__{sid}.jsonl"
        }
        session_files.add(jsonl_path)
        session_files = sorted(session_files, key=lambda p: (p.parent.name, p.name))

        for sf in session_files:
            declared_files.add(sf.resolve())

        seq_state: dict[str, Any] = {"seen": {}, "last": -1}
        agg_count = 0
        for sf in session_files:
            fstats = validate_jsonl_file(
                sf, event_validator, team_id, github_login, tool, sid, report,
                seq_state=seq_state,
            )
            agg_count += fstats["count"]

        declared_count = session.get("event_count", -1)
        if declared_count != agg_count:
            report.err(
                f"{manifest_path}: session[{idx}] {sid!r}: event_count mismatch: "
                f"manifest={declared_count}, actual={agg_count} "
                f"(aggregated across {len(session_files)} file(s))"
            )

    for jsonl_path in member_dir.rglob("*.jsonl"):
        if jsonl_path.resolve() not in declared_files:
            report.warn(
                f"{jsonl_path}: orphan file (exists but not in manifest.sessions)"
            )


def validate_manifest(
    logs_dir: Path,
    manifest_validator: Draft7Validator,
    event_validator: Draft7Validator,
    report: Report,
) -> None:
    # Two invocation modes are supported:
    #   1. logs_dir = <repo>/logs/        → iterate member subdirs
    #   2. logs_dir = <repo>/logs/<login> → validate that single member only
    if (logs_dir / "manifest.json").exists():
        repo_root = logs_dir.parent.parent
        _validate_one_member(logs_dir, repo_root, manifest_validator, event_validator, report)
        return

    repo_root = logs_dir.parent
    member_dirs = [d for d in logs_dir.iterdir() if d.is_dir() and (d / "manifest.json").exists()]
    if not member_dirs:
        report.err(f"{logs_dir}: no member directories with manifest.json found")
        return
    for member_dir in sorted(member_dirs):
        _validate_one_member(member_dir, repo_root, manifest_validator, event_validator, report)


